-- ZENVIO ONE v0.5 — BLACKBOX, WHAT IF and EVOLVE (additive)
create table if not exists public.zenvio_blackbox_records (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.zenvio_organizations(id) on delete cascade, record_type text not null check(record_type in ('document','decision','meeting','contract','policy','customer_note','project','lesson','other')), title text not null check(char_length(trim(title)) between 2 and 200), content text not null check(char_length(trim(content)) between 1 and 30000), source_label text, source_date date, owner_label text, tags text[] not null default '{}', created_by uuid not null references auth.users(id) on delete restrict, updated_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists zenvio_blackbox_org_idx on public.zenvio_blackbox_records(organization_id,record_type,source_date desc);
create index if not exists zenvio_blackbox_search_idx on public.zenvio_blackbox_records using gin(to_tsvector('english',coalesce(title,'')||' '||coalesce(content,'')));
create table if not exists public.zenvio_whatif_scenarios (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.zenvio_organizations(id) on delete cascade, title text not null check(char_length(trim(title)) between 3 and 180), description text, baseline_monthly_revenue numeric(18,2) not null default 0 check(baseline_monthly_revenue>=0), baseline_monthly_cost numeric(18,2) not null default 0 check(baseline_monthly_cost>=0), revenue_change_pct numeric(8,2) not null default 0 check(revenue_change_pct between -100 and 1000), cost_change_pct numeric(8,2) not null default 0 check(cost_change_pct between -100 and 1000), one_time_investment numeric(18,2) not null default 0 check(one_time_investment>=0), assumptions text not null default '', result jsonb not null default '{}'::jsonb, status text not null default 'draft' check(status in ('draft','reviewed','archived')), created_by uuid not null references auth.users(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists zenvio_whatif_org_idx on public.zenvio_whatif_scenarios(organization_id,created_at desc);
create table if not exists public.zenvio_evolve_items (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.zenvio_organizations(id) on delete cascade, title text not null check(char_length(trim(title)) between 3 and 180), area text not null check(area in ('sales','finance','operations','marketing','support','people','product','other')), recommendation text not null check(char_length(trim(recommendation)) between 3 and 3000), expected_outcome text, baseline_value numeric(18,4), target_value numeric(18,4), actual_value numeric(18,4), metric_unit text, baseline_date date, measured_date date, status text not null default 'proposed' check(status in ('proposed','approved','in_progress','measured','adopted','not_effective','rejected')), evidence_note text, created_by uuid not null references auth.users(id) on delete restrict, updated_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists zenvio_evolve_org_idx on public.zenvio_evolve_items(organization_id,status,created_at desc);
alter table public.zenvio_blackbox_records enable row level security; alter table public.zenvio_whatif_scenarios enable row level security; alter table public.zenvio_evolve_items enable row level security;
drop policy if exists zenvio_blackbox_select on public.zenvio_blackbox_records; create policy zenvio_blackbox_select on public.zenvio_blackbox_records for select to authenticated using(public.zenvio_is_member(organization_id));
drop policy if exists zenvio_blackbox_insert on public.zenvio_blackbox_records; create policy zenvio_blackbox_insert on public.zenvio_blackbox_records for insert to authenticated with check(created_by=auth.uid() and public.zenvio_has_role(organization_id,array['owner','admin']));
drop policy if exists zenvio_blackbox_update on public.zenvio_blackbox_records; create policy zenvio_blackbox_update on public.zenvio_blackbox_records for update to authenticated using(public.zenvio_has_role(organization_id,array['owner','admin'])) with check(public.zenvio_has_role(organization_id,array['owner','admin']) and updated_by=auth.uid());
drop policy if exists zenvio_blackbox_delete on public.zenvio_blackbox_records; create policy zenvio_blackbox_delete on public.zenvio_blackbox_records for delete to authenticated using(public.zenvio_has_role(organization_id,array['owner','admin']));
drop policy if exists zenvio_whatif_select on public.zenvio_whatif_scenarios; create policy zenvio_whatif_select on public.zenvio_whatif_scenarios for select to authenticated using(public.zenvio_is_member(organization_id));
drop policy if exists zenvio_whatif_insert on public.zenvio_whatif_scenarios; create policy zenvio_whatif_insert on public.zenvio_whatif_scenarios for insert to authenticated with check(created_by=auth.uid() and public.zenvio_has_role(organization_id,array['owner','admin']));
drop policy if exists zenvio_whatif_update on public.zenvio_whatif_scenarios; create policy zenvio_whatif_update on public.zenvio_whatif_scenarios for update to authenticated using(public.zenvio_has_role(organization_id,array['owner','admin'])) with check(public.zenvio_has_role(organization_id,array['owner','admin']));
drop policy if exists zenvio_whatif_delete on public.zenvio_whatif_scenarios; create policy zenvio_whatif_delete on public.zenvio_whatif_scenarios for delete to authenticated using(public.zenvio_has_role(organization_id,array['owner','admin']));
drop policy if exists zenvio_evolve_select on public.zenvio_evolve_items; create policy zenvio_evolve_select on public.zenvio_evolve_items for select to authenticated using(public.zenvio_is_member(organization_id));
drop policy if exists zenvio_evolve_insert on public.zenvio_evolve_items; create policy zenvio_evolve_insert on public.zenvio_evolve_items for insert to authenticated with check(created_by=auth.uid() and public.zenvio_has_role(organization_id,array['owner','admin']));
drop policy if exists zenvio_evolve_update on public.zenvio_evolve_items; create policy zenvio_evolve_update on public.zenvio_evolve_items for update to authenticated using(public.zenvio_has_role(organization_id,array['owner','admin'])) with check(public.zenvio_has_role(organization_id,array['owner','admin']) and updated_by=auth.uid());
drop policy if exists zenvio_evolve_delete on public.zenvio_evolve_items; create policy zenvio_evolve_delete on public.zenvio_evolve_items for delete to authenticated using(public.zenvio_has_role(organization_id,array['owner','admin']));
drop trigger if exists zenvio_blackbox_touch on public.zenvio_blackbox_records; create trigger zenvio_blackbox_touch before update on public.zenvio_blackbox_records for each row execute function public.zenvio_touch_updated_at();
drop trigger if exists zenvio_whatif_touch on public.zenvio_whatif_scenarios; create trigger zenvio_whatif_touch before update on public.zenvio_whatif_scenarios for each row execute function public.zenvio_touch_updated_at();
drop trigger if exists zenvio_evolve_touch on public.zenvio_evolve_items; create trigger zenvio_evolve_touch before update on public.zenvio_evolve_items for each row execute function public.zenvio_touch_updated_at();
grant select,insert,update,delete on public.zenvio_blackbox_records,public.zenvio_whatif_scenarios,public.zenvio_evolve_items to authenticated;